    public PerformanceReview testCreate() throws Throwable {
    PerformanceReview entity = null;

    LOGGER.info( "PerformanceReviewTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a PerformanceReview");

    StringBuilder msg = new StringBuilder( "-- Failed to create a PerformanceReview" );

    try {
        entity = service.createPerformanceReview( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getPerformanceReviewId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a PerformanceReview with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

