    /**
     * Tests getting all PerformanceReviews.
     *
     * @return    Collection
     */
    public List<PerformanceReview> testGetAll() throws Throwable {
    LOGGER.info( "PerformanceReviewTest:testGetAll() - Retrieving Collection of PerformanceReviews:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PerformanceReview : " );
    List<PerformanceReview> collection  = null;

    try {
        // call the static get method on the PerformanceReviewService
        collection = service.getAllPerformanceReview();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PerformanceReview currEntity  = null;
            Iterator<PerformanceReview> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPerformanceReviewId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

